writing.exampleCode:
let point = (3, -7);

match point {
    (0, 0) => println!("origin"),
    (x, 0) | (0, x) => println!("axis at {x}"),
    (x, y) if y < 0 => println!("below: {x},{y}"),
    (x, y) => println!("somewhere: {x},{y}"),
}

